#!/data/data/com.termux/files/usr/bin/bash
# OBSIDIANTI_MWNI_RETARGET_PLUGIN_v1.4.0
# Pinned free Mwni addon. Termux Git ONLY. No canonical model mutations.
set -euo pipefail
SELF="$(readlink -f "${BASH_SOURCE[0]}")"
PAYLOAD_SHA256=fac848ed0fe39d7a2825a1b3efcd66afb853d7c947a64d6c35c2732d0dc0148c
if [[ "${1:-}" == '--selftest' ]]; then
  bash -n "$SELF"
  echo "LAUNCHER_SYNTAX=PASS"
  echo "PINNED_VENDOR_SHA=8c91ff4f4d898bab835b3587f17585487056b60b"
  exit 0
fi
if ! command -v python3 >/dev/null || ! command -v git >/dev/null || ! command -v base64 >/dev/null || ! command -v sha256sum >/dev/null; then
  echo 'BLOCKED: Python3, Git, base64 and sha256sum must exist in Termux' >&2; exit 2
fi
TMP="$(mktemp -d "${TMPDIR:-/data/data/com.termux/files/usr/tmp}/obs-mwni-v140.XXXXXXXX")"
trap 'rm -rf "$TMP"' EXIT
ENTRY="$(awk '/^__PAYLOAD_BELOW__$/{print NR+1; exit}' "$SELF")"
if [[ -z "$ENTRY" ]]; then echo 'BLOCKED: embedded payload marker missing' >&2; exit 3; fi
tail -n +"$ENTRY" "$SELF" | base64 -d > "$TMP/payload.tar.gz"
printf '%s  %s\n' "$PAYLOAD_SHA256" "$TMP/payload.tar.gz" | sha256sum -c -
tar -tzf "$TMP/payload.tar.gz" | grep -Eq '^driver.py$' || { echo 'BLOCKED: expected driver missing' >&2; exit 4; }
mkdir -p "$TMP/packet"
tar -xzf "$TMP/payload.tar.gz" -C "$TMP/packet" --no-same-owner --no-same-permissions
if [[ "${1:-}" == '--verify-packet' ]]; then
 python3 - "$TMP/packet" <<'PYCODE'
import json,sys,hashlib,pathlib
p=pathlib.Path(sys.argv[1]);d=json.loads((p/'manifest.json').read_text());assert set(d)=={'driver.py','blender_trial.py','test_driver.py','contract.json'}
for n,v in d.items():assert hashlib.sha256((p/n).read_bytes()).hexdigest()==v
print('PACKET_INTEGRITY=PASS',len(d),'members')
PYCODE
 exit 0
fi
printf 'CAMPAIGN=OBSIDIANTI_MWNI_RETARGET_PLUGIN_v1.4.0\n'
printf 'AUTHORITY=TERMUX_GIT_ONLY\n'
printf 'LAUNCHER_SHA256=%s\n' "$(sha256sum "$SELF" | cut -d' ' -f1)"
printf 'PAYLOAD_SHA256=%s\n' "$PAYLOAD_SHA256"
python3 "$TMP/packet/driver.py" "$TMP/packet" "$SELF" "$(sha256sum "$SELF" | cut -d' ' -f1)"
exit $?
__PAYLOAD_BELOW__

